// Validates the request the OneJarc server forwards (POST, JSON body, X-OneJarc-* headers).
// Output: { ok: true, id, ... } or { ok: false, status, body } (answered by "Respond").
const req = $input.first().json;
const headers = req.headers || {};
const body = req.body && typeof req.body === 'object' && !Array.isArray(req.body) ? req.body : null;
const fail = (status, message) => [{ json: { ok: false, status, body: { success: false, error: message } } }];
const isObject = (v) => !!v && typeof v === 'object' && !Array.isArray(v);

// The OneJarc server only forwards admin actions for admins and always sends this header.
// (Real protection for the URL itself: add Header Auth to the Webhook node later.)
if (String(headers['x-onejarc-user-is-admin'] || '').toLowerCase() !== 'true') return fail(403, 'Admin access is required.');
if (!body) return fail(400, 'The request body must be a JSON object.');
const id = typeof body.id === 'string' ? body.id.trim() : '';
if (!id || id.length > 200 || /[\u0000-\u001f]/.test(id)) return fail(400, 'A tool id is required.');

// Matches the document whether its _id is an ObjectId or a string, or whether it uses a
// separate string "id" field (get-tools.js accepts either). $literal stops an id that starts
// with "$" from being read as a field path.
const match = { $or: [{ $expr: { $eq: [{ $toString: '$_id' }, { $literal: id }] } }, { id }] };
return [{ json: { ok: true, id, query: JSON.stringify(match) } }];

// deletedCount 0 means no document matched the id.
const input = $('Validate input').first().json;
const r = $input.first().json || {};
if (r.error || typeof r.deletedCount !== 'number') return [{ json: { status: 500, body: { success: false, error: 'The database delete failed. Check the n8n execution log.' } } }];
if (r.deletedCount === 0) return [{ json: { status: 404, body: { success: false, error: 'This tool no longer exists in the database. Reload the catalog.' } } }];
return [{ json: { status: 200, body: { success: true, id: input.id } } }];

// Error output of a MongoDB node (connection, credential, query or write failure).
// Details stay in the n8n execution log; the admin sees a short JSON error.
return [{ json: { status: 500, body: { success: false, error: 'The database operation failed. Check the n8n execution log.' } } }];
